import{_ as e,o,c as r,a3 as t}from"./chunks/framework.BFeCKmyl.js";const f=JSON.parse('{"title":"Colapsar e fixar seções do Painel do Servidor","description":"","frontmatter":{"title":"Colapsar e fixar seções do Painel do Servidor","id":"eproc-icones-secoes-colapsadas-painel","plataforma":"eproc","grupo":"Geral do eproc","plano":"free","desde":"1.1.4","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-icones-secoes-colapsadas-painel"}]]},"headers":[],"relativePath":"funcionalidades/eproc-icones-secoes-colapsadas-painel.md","filePath":"funcionalidades/eproc-icones-secoes-colapsadas-painel.md"}'),d={name:"funcionalidades/eproc-icones-secoes-colapsadas-painel.md"};function s(i,a,l,c,n,p){return o(),r("div",null,a[0]||(a[0]=[t('<h1 id="colapsar-e-fixar-secoes-do-painel-do-servidor" tabindex="-1">Colapsar e fixar seções do Painel do Servidor <a class="header-anchor" href="#colapsar-e-fixar-secoes-do-painel-do-servidor" aria-label="Permalink to &quot;Colapsar e fixar seções do Painel do Servidor&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>No Painel do Servidor, as seções recolhidas ocupam espaço. Este recurso transforma cada seção recolhida num ícone compacto, como um aplicativo, que a reabre com um clique. Também permite recolher qualquer seção, reordená-las e fixar uma delas com destaque visual.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, Painel do Servidor e Painel de Plantão.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra o Painel do Servidor.</li><li>Para recolher uma seção, clique no botão de recolher no título dela (&quot;Recolher seção&quot;). Ela vira um ícone.</li><li>Para reabrir, clique no ícone (&quot;Mostrar ...&quot;). A seção volta ao fim da sequência das seções abertas.</li><li>Para mudar a ordem, use as setas no título (&quot;Mover seção para cima&quot; / &quot;Mover seção para baixo&quot;).</li><li>Para fixar uma seção, clique no alfinete (&quot;Destacar esta seção&quot;). Ela ganha borda e brilho e, ao carregar a página, a tela rola até ela. Só uma seção fica fixada por vez.</li></ol><p>Tudo é lembrado separadamente para cada perfil/unidade do eproc.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Atualizar dados da seção automaticamente (ao carregar já aberta ou ao reabrir)</td><td>ligada</td><td>Atualiza o conteúdo da seção quando ela é aberta.</td></tr><tr><td>Aplicar destaque visual à seção fixada</td><td>ligada</td><td>Borda na seção fixada.</td></tr><tr><td>Cor da borda do destaque</td><td>#007bff</td><td>Só com o destaque ligado.</td></tr><tr><td>Aplicar efeito glow</td><td>ligada</td><td>Brilho em volta da seção fixada. Só com o destaque ligado.</td></tr><tr><td>Cor do glow</td><td>#00d9ff</td><td>Só com o glow ligado.</td></tr><tr><td>Centralizar rolagem até a seção fixada ao carregar a página</td><td>ligada</td><td>Leva a tela até a seção fixada.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Sem nenhuma seção fixada ainda, o Relatório Geral é fixado por padrão.</li><li>Para as seções que o eproc já permite recolher, o estado aberto/recolhido continua sendo guardado pelo próprio eproc (&quot;Aberto ao acessar painel&quot;).</li></ul>',12)]))}const h=e(d,[["render",s]]);export{f as __pageData,h as default};
